while (nextPeriodId) {
    const subNextResult = ec.service.sync().name("mantle.party.TimeServices.get#NextTimePeriod")
            .parameter("timePeriodId", nextPeriodId).call()
    nextPeriodId = subNextResult.nextTimePeriodId
    if (nextPeriodId) subsequentPeriodIds.push(nextPeriodId)
}

