{glAccountId:glAccountOrgTimePeriod.glAccountId, organizationPartyId:timePeriod.partyId,
                                            timePeriodId:subsequentPeriodId, beginningBalance:0, postedDebits:0, postedCredits:0,
                                            postedDebitsNoClosing:0, postedCreditsNoClosing:0, endingBalance:0}

actions.script:
function dateOf(value) {
    const text = String(value)
    if (/^-?\d+$/.test(text)) { const at = new Date(Number(text)); return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate())) }
    const [y, m, d] = text.slice(0, 10).split('-').map(Number)
    return new Date(Date.UTC(y, m - 1, d))
}
basisYear = dateOf(basisDate).getUTCFullYear()
basisMonth = dateOf(basisDate).getUTCMonth()

while (curSubPeriodId) {
    const subNextResult = ec.service.sync().name("mantle.party.TimeServices.get#NextTimePeriod")
            .parameter("timePeriodId", curSubPeriodId).call()
    curSubPeriodId = subNextResult.nextTimePeriodId
    if (curSubPeriodId) subsequentPeriodIds.push(curSubPeriodId)
}

entity-make-value.map:
{glAccountId:glAccountOrgTimePeriod.glAccountId, organizationPartyId:timePeriod.partyId,
                                timePeriodId:subsequentPeriodId, beginningBalance:0, postedDebits:0, postedCredits:0,
                                postedDebitsNoClosing:0, postedCreditsNoClosing:0, endingBalance:0}

iterate.script:
const transSummaryListSize = transSummaryList.length
let updatedCount = 0
for (let i = 0; i < transSummaryListSize; i++) {
    const transSummary = transSummaryList[i]
    const glAccountId = transSummary.glAccountId

    let isDebit = glAccountIsDebitMap[glAccountId]
    if (!isDebit) {
        const glAccount = ec.entity.find("mantle.ledger.account.GlAccount").condition("glAccountId", glAccountId).useCache(true).one()
        isDebit = glAccount.isDebit
        glAccountIsDebitMap[glAccountId] = isDebit
    }
    const isDebitAccount = (isDebit === 'Y')

    // credit rows sort before debit rows for the same account, so the debit row (if any) is next
    let debitTransSummary = null
    const isCredit = transSummary.debitCreditFlag === 'C'
    if (isCredit && (i + 1) < transSummaryListSize) {
        debitTransSummary = transSummaryList[i + 1]
        if (debitTransSummary.debitCreditFlag === 'D' && debitTransSummary.glAccountId === glAccountId) {
            i++
        } else {
            debitTransSummary = null
        }
    }

    let glAccountOrganization = ec.entity.find("mantle.ledger.account.GlAccountOrganization")
            .condition("glAccountId", glAccountId).condition("organizationPartyId", organizationPartyId)
            .forUpdate(true).one()
    if (glAccountOrganization == null) {
        glAccountOrganization = ec.entity.makeValue("mantle.ledger.account.GlAccountOrganization")
        glAccountOrganization.set("glAccountId", glAccountId)
        glAccountOrganization.set("organizationPartyId", organizationPartyId)
        glAccountOrganization.create()
    }

    let postedBalance = toDecimal(0)
    if (isCredit) {
        // based on account type add/subtract credit
        postedBalance = isDebitAccount ? postedBalance.subtract(transSummary.amount) : postedBalance.add(transSummary.amount)
        // if debitTransSummary != null based on account type subtract/add debit
        if (debitTransSummary != null) {
            postedBalance = isDebitAccount ? postedBalance.add(debitTransSummary.amount) : postedBalance.subtract(debitTransSummary.amount)
        }
    } else {
        // based on account type subtract/add debit
        postedBalance = isDebitAccount ? postedBalance.add(transSummary.amount) : postedBalance.subtract(transSummary.amount)
    }

    glAccountOrganization.set("postedBalance", postedBalance)
    glAccountOrganization.set("balanceLastUpdated", nowTimestamp)
    glAccountOrganization.update()
    updatedCount++
}
gaoUpdated = gaoUpdated + updatedCount

// stop at the first period in timePeriodList, it carries the balances on when it is processed (see NOTE above)
while (curSubPeriodId && !listedPeriodIds.has(curSubPeriodId)) {
    const subNextResult = ec.service.sync().name("mantle.party.TimeServices.get#NextTimePeriod")
            .parameter("timePeriodId", curSubPeriodId).call()
    curSubPeriodId = subNextResult.nextTimePeriodId
    if (curSubPeriodId) subsequentPeriodIds.push(curSubPeriodId)
}

// a Map keeps the accounts in query order, which is the lock order
const transSummariesByGlAccountId = new Map()
for (const transSummary of transSummaryList) {
    if (!transSummariesByGlAccountId.has(transSummary.glAccountId)) transSummariesByGlAccountId.set(transSummary.glAccountId, [])
    transSummariesByGlAccountId.get(transSummary.glAccountId).push(transSummary)
}
let updatedCount = 0

for (const [glAccountId, accountSummaryList] of transSummariesByGlAccountId) {
    glAccountIdsWithTrans.push(glAccountId)

    let isDebit = glAccountIsDebitMap[glAccountId]
    if (!isDebit) {
        const glAccount = ec.entity.find("mantle.ledger.account.GlAccount").condition("glAccountId", glAccountId).useCache(true).one()
        isDebit = glAccount.isDebit
        glAccountIsDebitMap[glAccountId] = isDebit
    }
    const isDebitAccount = (isDebit === 'Y')

    let glAccountOrgTimePeriod = ec.entity.find("mantle.ledger.account.GlAccountOrgTimePeriod")
            .condition("glAccountId", glAccountId).condition("organizationPartyId", organizationPartyId)
            .condition("timePeriodId", timePeriodId).forUpdate(true).one()
    let foundRecord = true
    if (glAccountOrgTimePeriod == null) {
        foundRecord = false
        glAccountOrgTimePeriod = ec.entity.makeValue("mantle.ledger.account.GlAccountOrgTimePeriod")
        glAccountOrgTimePeriod.set("glAccountId", glAccountId)
        glAccountOrgTimePeriod.set("organizationPartyId", organizationPartyId)
        glAccountOrgTimePeriod.set("timePeriodId", timePeriodId)
        glAccountOrgTimePeriod.set("beginningBalance", toDecimal(0))
        glAccountOrgTimePeriod.create()
    }

    let postedDebits = toDecimal(0)
    let postedCredits = toDecimal(0)
    let postedDebitsNoClosing = toDecimal(0)
    let postedCreditsNoClosing = toDecimal(0)

    for (const transSummary of accountSummaryList) {
        if (transSummary.debitCreditFlag === 'C') {
            postedCredits = postedCredits.add(transSummary.amount)
            if (transSummary.acctgTransTypeEnumId !== 'AttNetIncomeClosing') postedCreditsNoClosing = postedCreditsNoClosing.add(transSummary.amount)
        } else {
            postedDebits = postedDebits.add(transSummary.amount)
            if (transSummary.acctgTransTypeEnumId !== 'AttNetIncomeClosing') postedDebitsNoClosing = postedDebitsNoClosing.add(transSummary.amount)
        }
    }

    // calculate endingBalance from beginningBalance and posted debits/credits
    const beginningBalance = toDecimal(glAccountOrgTimePeriod.beginningBalance ?? 0)
    const endingBalance = isDebitAccount ? beginningBalance.add(postedDebits).subtract(postedCredits)
            : beginningBalance.subtract(postedDebits).add(postedCredits)

    const origGlAccountOrgTimePeriod = glAccountOrgTimePeriod.cloneValue()
    glAccountOrgTimePeriod.set("postedDebits", postedDebits)
    glAccountOrgTimePeriod.set("postedCredits", postedCredits)
    glAccountOrgTimePeriod.set("postedDebitsNoClosing", postedDebitsNoClosing)
    glAccountOrgTimePeriod.set("postedCreditsNoClosing", postedCreditsNoClosing)
    glAccountOrgTimePeriod.set("endingBalance", endingBalance)
    glAccountOrgTimePeriod.set("balanceLastUpdated", nowTimestamp)
    glAccountOrgTimePeriod.update()
    updatedCount++

    const differs = (orig, value) => orig == null || !value.eq(orig)
    if (foundRecord && (differs(origGlAccountOrgTimePeriod.postedDebits, postedDebits) ||
            differs(origGlAccountOrgTimePeriod.postedCredits, postedCredits) ||
            differs(origGlAccountOrgTimePeriod.postedDebitsNoClosing, postedDebitsNoClosing) ||
            differs(origGlAccountOrgTimePeriod.postedCreditsNoClosing, postedCreditsNoClosing))) {
        ec.logger.info(`In recalculate GLAOS updated account ${glAccountId} period ${timePeriodId} debit? ${isDebit} with wrong posted amounts; beginningBalance=${glAccountOrgTimePeriod.beginningBalance}, postedDebits was ${origGlAccountOrgTimePeriod.postedDebits} is ${glAccountOrgTimePeriod.postedDebits}, postedCredits was ${origGlAccountOrgTimePeriod.postedCredits} is ${glAccountOrgTimePeriod.postedCredits}, postedDebitsNoClosing was ${origGlAccountOrgTimePeriod.postedDebitsNoClosing} is ${glAccountOrgTimePeriod.postedDebitsNoClosing}, postedCreditsNoClosing was ${origGlAccountOrgTimePeriod.postedCreditsNoClosing} is ${glAccountOrgTimePeriod.postedCreditsNoClosing}, endingBalance was ${origGlAccountOrgTimePeriod.endingBalance} is ${glAccountOrgTimePeriod.endingBalance}`)
    }

    // update balances for all existing subsequent periods
    let lastGlAccountOrgTimePeriod = glAccountOrgTimePeriod
    for (const subsequentPeriodId of subsequentPeriodIds) {
        let nextGlAccountOrgTimePeriod = ec.entity.find("mantle.ledger.account.GlAccountOrgTimePeriod")
                .condition("glAccountId", glAccountId).condition("organizationPartyId", organizationPartyId)
                .condition("timePeriodId", subsequentPeriodId).forUpdate(true).one()
        if (nextGlAccountOrgTimePeriod == null) {
            nextGlAccountOrgTimePeriod = ec.entity.makeValue("mantle.ledger.account.GlAccountOrgTimePeriod")
            nextGlAccountOrgTimePeriod.set("glAccountId", glAccountId)
            nextGlAccountOrgTimePeriod.set("organizationPartyId", organizationPartyId)
            nextGlAccountOrgTimePeriod.set("timePeriodId", subsequentPeriodId)
            nextGlAccountOrgTimePeriod.set("beginningBalance", toDecimal(0))
            nextGlAccountOrgTimePeriod.set("postedDebits", toDecimal(0))
            nextGlAccountOrgTimePeriod.set("postedCredits", toDecimal(0))
            nextGlAccountOrgTimePeriod.set("postedDebitsNoClosing", toDecimal(0))
            nextGlAccountOrgTimePeriod.set("postedCreditsNoClosing", toDecimal(0))
            nextGlAccountOrgTimePeriod.set("endingBalance", toDecimal(0))
            nextGlAccountOrgTimePeriod.create()
        }

        nextGlAccountOrgTimePeriod.set("endingBalance", toDecimal(nextGlAccountOrgTimePeriod.endingBalance ?? 0)
                .subtract(nextGlAccountOrgTimePeriod.beginningBalance ?? 0).add(lastGlAccountOrgTimePeriod.endingBalance ?? 0))
        nextGlAccountOrgTimePeriod.set("beginningBalance", lastGlAccountOrgTimePeriod.endingBalance)
        nextGlAccountOrgTimePeriod.set("balanceLastUpdated", nowTimestamp)
        nextGlAccountOrgTimePeriod.update()

        lastGlAccountOrgTimePeriod = nextGlAccountOrgTimePeriod
    }
}
gaotpUpdated = gaotpUpdated + updatedCount

entity-make-value.map:
{glAccountId:glAccountOrgTimePeriod.glAccountId, organizationPartyId:timePeriod.partyId,
                                        timePeriodId:subsequentPeriodId, beginningBalance:0, postedDebits:0, postedCredits:0,
                                        postedDebitsNoClosing:0, postedCreditsNoClosing:0, endingBalance:0}
